import{_ as t,c as a,o as e,ah as s}from"./chunks/framework.Dnh4IO1K.js";const h=JSON.parse('{"title":"童溪易传卷二十一","description":"童溪易传 - 童溪易传卷二十一","frontmatter":{"title":"童溪易传卷二十一","description":"童溪易传 - 童溪易传卷二十一"},"headers":[],"relativePath":"zh/classics/tongxi/022.md","filePath":"zh/classics/tongxi/022.md"}'),r={name:"zh/classics/tongxi/022.md"};function i(o,p,n,c,_,l){return e(),a("div",null,[...p[0]||(p[0]=[s('<h1 id="童溪易传卷二十一" tabindex="-1">童溪易传卷二十一 <a class="header-anchor" href="#童溪易传卷二十一" aria-label="Permalink to “童溪易传卷二十一”">​</a></h1><p>钦定四库全书</p><p>宋王宗传撰䷬</p><p>坤下兑上 「萃」，亨，王假有庙，利见大人，亨，利贞。用大牲吉，利有攸往。彖曰：「萃」，聚也。顺以说，刚中而应，故聚也。「王假有庙」，致孝享也。「利见大人，亨」，聚以正也。「用大牲吉，利有攸往」，顺天命也。观其所聚，而天地万物之情可见矣。易之有「萃」云者，谓天也、人也、鬼神也、君与臣也、民也、物也，交相会通之时也。故其卦德曰「萃，亨」。而彖则释之曰：「萃，聚也。」夫「萃」之所以为聚者，合「兑」与「坤」而言之，则曰「顺以说」；即五与二而言之，则曰「刚中而应」，此萃聚之故也。夫「坤」，顺也，而在下则下有以顺乎上也；「兑」，说也，而在上则上有以说乎下也。下既有以顺乎上，而上又有以说乎下，此上下之「萃」也。以九居五，刚而中者也。上有刚中之君，而下应乎柔中之臣，刚柔相应，君臣聚会，此君臣之萃也。所谓萃聚之故，如斯而已矣。故曰：「萃，聚也。顺以说，刚中而应，故聚也。王假有庙，致孝享也。」此又言人神之萃也。胡安定曰：夫人之生，则精神萃于身。及其死也，虽欲见其容貌，而有不可得。王者观萃之卦，设为庙祧，以萃祖宗精神于其闲，以尽孝子之心，使天下当「萃」之时，皆知尊事其祖先也。王，谓九五也。假，至也，尽也。所谓「致孝享」是也。利见大人，亨，聚以正也。此又言君民之萃也。大人，亦谓五也。夫当「萃」之时，天下之人所以惟见大人之为利者，以九五大人所以萃天下者，以其有是中正之德故也。河南曰：人聚则乱，物聚则紊，非大人治之，则萃所以致争乱也。萃不以正，则人聚为苟合，财聚为悖入，安得亨也？故利在于正。用大牲吉，利有攸往，顺天命也。此又言天人之萃也。夫时在天，随乎时者在乎人。当损之时，「二簋可用享」，则「萃」之时用大牲非吉欤？当剥之时，不利有攸往，则「萃」之时，有攸往非利欤？盖不如是，非所谓顺天命也。天命即天理也，随时而动，无违天理，此所谓「顺天命也」。「用大牲吉」，亦承上文所谓「王假有庙」，而明「用大牲」之意。然当此之时，凡事皆吉于用大，亦不特大牲而已也。成大功，立大事，兴大利，去大害，凡此皆吉于用大者也。故继之以「利有攸往」，谓凡有所往，惟此时为利故也。夫观坤兑之顺说，而知上下之萃；观二五之相应，而知君臣之萃；观致孝以享庙，而知人神之萃；观以正聚人，而又知君民之萃；观天命之不可不顺，而又知天人之萃。则天地万物所以萃聚之情，岂容有所遁乎哉？故蔽之曰：「观其所聚，而天地万物之情可见矣。」程河南曰：「凡有者皆聚也。有无动静始终之理，聚散而已。故观其所聚，而天地万物之情可见矣。」</p><p>象曰：泽上于地，萃。君子以除戎器，戒不虞。</p><p>泽水上聚于地，则其聚者多矣，故为萃之象。然所聚者既多，则播荡汇漾之患生矣。故地大而物众，人繁而事丛，则兼取并夺之祸，常生于此时。若以为时方和会也，而忘其所可戒，此正秦人夷名城而销锋镝者也。夫四海已囊括矣，天下已席卷矣，当此之时，自以为豪杰既徂，海内一统，子孙万世帝王之业，故向之天下之兵，今也聚之咸阳，为十二金人，宜其无有可虑者矣。居无何，陈涉以氓隶之人，斩木为兵，揭竿为旗，天下云合响应，而秦亡矣。是何也？不知不虞之为可戒也。龚深甫曰：「兵作于睽，偃于萃，萃久则弊。」然则除其弊而新之，惟此时为然。兵法曰：天下虽安，忘战必危。此之谓也。初六：有孚不终，乃乱乃萃，若号，一握为笑，勿恤，往无咎。象曰：「乃乱乃萃」，其志乱也。</p><p>初与四居相应之地，以阴而应阳，萃之正也。然三以无应与四相此，而有近而相聚之嫌，故初之「孚」于四也，而不终其孚焉，故曰「乃乱」，谓相信之志疑乱而不一也。然居萃聚之时，上下相求，下顺而上说，故初之志虽疑乱而不一，而四也必说而应之，故曰「乃萃」。「若号」，谓「乃乱」也；「一握为笑」，谓「乃萃」也。夫初之志既疑乱而不一也，故有「若号」之象焉，谓以忧疑自沮也。四也说以应之，则一握之顷，复变号啕而为笑乐矣，谓得其所聚也。夫如是，则初也又何必忧疑自沮而至于若号乎？故戒之曰「勿恤」。夫既勿用忧恤而往应于四，则亦孰我咎乎？故又勉之曰「往无咎」。大抵初以阴柔之才而居下位，才与位俱不足者也。当「萃」之时，其才与位既俱不足，而六三又以无应而与四有相聚之嫌，故初疑四之不己应也，而相信之志至于疑乱而不一。圣人于此，可不戒之而勉之乎？</p><p>六二：引吉，无咎。孚乃利用礿。象曰：「引吉无咎」，中未变也。孟子曰：「丈夫生而愿为之有室，女子生而愿为之有家。父母之心，人皆有之。」不待父母之命、媒妁之言，钻穴隙相窥，逾墙相从，则父母国人皆恶之。此言正喻君臣相聚之道然也。故又继之曰：「古之人未尝不欲仕也，又恶不由其道。」不由其道而往，是钻穴隙之类也。夫必由其道而往，此六二之所以「吉」于有引也。盖以六居二，正也；而九五在上，亦正也。二、五居相应之地，而其聚也以正，故无不由其道之失。五之于二也，既有引而进之之礼，则二之于五也，亦必吉于引矣。故其聚也以正，其谁咎之？夫「孚」者，「萃」之本也。二以正道许五，则所谓中心之诚然者，未始或变也。如此，则上下相聚，不待文饰而诚意交通矣。犹之祭也，以诚敬为主，故虽简薄，可用以荐也。「孚乃利用礿」，「礿」，祭之简薄也，谓诚意交通，又何以文饰为哉？虽然，同此时也，彖以「用大牲」为「吉」，而六二以「用礿」为「利」，何也？曰：备物者，王者所以随其时；「有孚」者，人臣所以通乎上。</p><p>六三：萃如嗟如，无攸利。往无咎，小吝。象曰：「往无咎」，上巽也。</p><p>当「萃」之时，以阴比阳，若有所「萃」也，故曰「萃如」。然「萃」贵于正，三之于四，非「萃」之正也，故若有「萃」而实无所萃也，故曰「嗟如」，谓欲「萃」于四而不𫉬也。夫欲「萃」而无所「萃」，又何利乎？故又曰「无攸利」。夫三与上居相应之地，虽非正应，犹愈于无所「萃」者。若往而与之「萃」，则亦所谓以类聚也。又况各居顺说之极，下顺而上说，以同类相与，又何咎欤？故又勉之曰「往无咎」、曰「小吝」云者，夫以阴与阳「萃」，则以晦求明，以弱资强，而萃聚之道为有益也。今以阴「萃」阴，特求免于穷悴，「无萃」之嗟尔，何所益哉？此于萃聚之道小而吝也。上六无与为「萃」者，若六三者往而与之「萃」，则「巽」而受之，此亦上六之所欲也。故曰：「往无咎，上巽也。」九四：大吉，无咎。象曰：「大吉无咎」，位不当也。</p><p>当「萃」之时，上比九五之君，得君之聚也；下比群阴，得民之聚也。得上下之聚，可谓善矣。然四以阳居阴，非正也。虽得上下之聚，必「大吉」然后「无咎」。「大」，周徧之义也。无不周，然后为大。夫天下之聚，固有不由正道而得者。非理枉道而得君者，自古多矣；非理枉道而得民者，盖亦有之，如齐之田常、鲁之季氏是也。其得为「大吉」乎？得为「无咎」乎？此程河南之说也。九五：萃有位，无咎。匪孚，元永贞，悔亡。象曰：「萃有位」，志未光也。</p><p>五，「萃」之主也。夫当「萃」之时，为「萃」之主，莫大于有其位，又莫大于有其道。盖位也者，所以一天下之聚者也；而道也者，又所以久天下之聚者也。九五曰「萃有位」，则所以一天下之聚者，谓有是位也。又曰「元永贞」，则所以久天下之聚者，又必有其道也。夫当「萃」之时，有是位而无是道，则九五之志岂得谓之光大矣乎？虽能「无咎」，而天下不我信者亦众矣，故曰「匪孚」。谓天下之人容有言曰：上之人但以位而萃我也，而其道则未至也，此岂能无「未光」之悔乎？故必「元永贞」而后「悔亡」。「元」，始也。「永」，终也。「贞」，不变之谓也。惟夫九五之德，居中履正，而能终始不变焉，则「萃」天下之道无余事矣，故无未光之悔而曰「悔亡」也。程河南曰：「元永贞」者，君之德，民所归也。故比天下之道与萃天下之道，在此三者。上六：赍咨涕洟，无咎。象曰：「赍咨涕洟」，未安上也。</p><p>夫以阴柔之才而处「萃」之上位，而欲下之已聚者，难矣。又况当「萃」之时，诸爻刚柔皆有其应，而上六独无焉，其安能居此上位乎？宜其赍咨嗟叹而至于涕洟也。郑康成曰：「目出曰涕，鼻出曰洟。」夫上六，「萃」之终也，说之极也。「萃」久则散，说极则悲，盖其𫝑然也。当是之时，比五而居上，此盖小人之得志者也，宜若得所「萃」矣。然「萃」久则散，说极则悲，向者以为甚安也，今也反以为未安焉。小人而乘非所据，故不能终保其位，大抵然也。其曰「无咎」云者，在君子以为无足咎之故也。䷭</p><p>巽下坤上 升元亨。用见大人，勿恤，南征吉。彖曰：柔以时升，巽而顺，刚中而应，是以大亨。「用见大人，勿恤」，有庆也。「南征吉」，志行也。</p><p>夫天下之事，有所谓日进而不穷者，盖亦顺夫理而已矣。夫苟于理而未顺，未有能日进而不穷者，此易之所以有升，而卦德则曰「元亨」也。夫升之所以「元亨」者，以「坤」居巽上而言之，则曰「柔以时升」。合巽与坤而言之，则曰「巽而顺」。指九二之于六五而言之，则曰「刚中而应」。此其所以「元亨」也。夫柔之为物，非能强进者也，自非务顺乎理，安能升乎？其曰「柔以时升」云者，时之在天也，积百刻而成日，积日而成月，积月而成时，积时而成岁。初若甚微，终则甚著。初若甚近，终则甚远。柔之能升也，盖亦如此而已矣。何也？与时俱升故也，故曰：柔以时升。「坤」，顺也。巽亦顺也。下巽而上顺，其曰「巽而顺」，则亦无适而不用其顺也。以此为升，非顺乎天理矣乎？以九居二，刚而中者也。上应六五柔中之君，故曰「刚中而应」。夫当升之时，虽曰以柔而升也，然犹之木也，其能自下而升诸上者，苟其中之不刚，则亦委靡而已矣。此又柔之不可无刚也。故以九二之刚中，而上应六五之柔中，内有所主，而外有所应，以此为「升」，是亦顺乎理者也。合是三者以言「升」，此「升」之所以「元亨」也。故曰：「是以大亨，用见大人，勿恤，有庆也。南征吉，志行也」。此又申言「大亨」之效，有所戒，有所勉，而使君子之必知所升也。夫升之所以大亨也如此，则用此道以见大人，又何忧其不升也？故二之与五，刚柔得中，君臣相应，何庆如之？夫苟或忧其不升而遽已焉，则安能大亨矣乎？其曰「勿恤」云者，戒之也。「南」，明方也。升之所谓「大亨」者，盖亦舍晦而趋明之谓也。故以「南征」为「吉」，而曰「志行」也。夫君子之志，亦志于明而已矣。不志于明，又安能大亨者也？其曰「南征」云者，又勉之也。夫圣人之彖「升」也，既言其所以大亨如此，又有所戒，又有所勉，为君子者，可不务乎？然则人臣之进君，学者之进学，临事而从长，皆然也。</p><p>象曰：地中生木，「升」，君子以顺德，积小以高大。</p><p>天下之物，由微以至著，自下而之上者，地中之生木也。何也？顺使然也。盖「坤」，顺也，「巽」亦顺也。以顺生顺，故「坤」地之中生「巽」之木，始于毫末，终于寻丈者，以顺故也。此「升」之象然也。德之在君子，亦犹木之于地也。何也？君子之性，顺也，而德出于性，亦顺物也。以顺生顺，故其积也不已，则始于小善，终于为圣为贤，其高且大，孰御焉？孟子曰：「孩提之童，无不知爱其亲；及其长也，无不知敬其兄。」夫爱亲，仁也；敬长，义也。君子之仁，始于爱亲而已；及其以爱亲之仁，积之而至于无所不爱，则仁满天下矣。君子之义，始于敬兄而已；及其以敬兄之义，积之而至于无所不敬，则义满天下矣。夫由爱亲而至于无所不爱，由敬兄而至于无所不敬者，非顺德不能也。吾故曰：天下之事，亦有所谓日进而不穷者，盖亦顺乎理而已矣。</p><p>初六：允升，大吉。象曰：「允升大吉」，上令志也。</p><p>「升」，以柔升者也。然初六以柔巽之才，居升之初，非有刚明之援与之同升，则亦未易升也。惟初也，以柔巽欲升之志，上承九二刚明之贤，故九二亦以其同体也，而与之合志以同升焉，故曰「允升」。「允」，信也。夫九二方且信我，而与我合志以同升焉，则其为吉也，孰大于此？盖谓之「大吉」，则当升之初，上下相信而不相疑，由此而升，则功业可以被天下矣。所谓吉之大者，实基于此故也。</p><p>九二：孚乃利用礿，无咎。象曰：九二之「孚」，有喜也。彖</p><p>曰：「刚中而应」，谓二之于五也。当柔升之时，卦惟二刚，而九二刚而中，又巽体也，故无过刚之失，而足以上应柔中之主，故曰：「孚乃利用礿，无咎。」谓二五刚柔之得中，而君臣之相应故也。夫君臣之志，患不相孚。苟孚也，则虽简薄可用也。何也？无事于文饰故也。故以用礿为「利」，谓以诚敬为主也。如是，当柔升之时，庸讵以过刚为咎乎？河南曰：「自古以刚强之臣事柔弱之君，又当升之时，非诚意于交，其能免咎乎？」夫九二能以诚意上通于君，亦岂为臣之道，无咎而已乎？道合而志行，则其利泽可以被于天下，此九二之「孚」所以「有喜」也。「萃」以上萃下者也，故六二「引吉，无咎」，而复以「孚乃用礿」继之。升以下升上者也，故九二曰「孚乃利用礿」，而复以「无咎」继之。此虽升者萃之反，而九者六之反也，而以诚敬上通乎五，则亦一也。</p><p>九三：升虚邑。象曰：「升虚邑」，无所疑也。</p><p>夫当柔升之时，而九三之升也，乃独以刚过之才升焉，如涉无人之墟，故有「升虚邑」之象。夫其升也，如「升虚邑」然，又何疑沮之有哉？龚深甫有曰：「李元量、耿希道皆以此爻为汤武之升，而以六五为舜禹之升。盖</p><p>六四王用亨于岐山，既为文王之升矣，则以此爻为汤武，六五为舜禹故也。今辄依之。」李元量博士曰：「初与二，臣之升也。过乎二，则非纯臣之象。是以九三之升，惟汤武足以当之。方夏之未、商之季，法度废矣，礼乐堕矣，故国虽大，谓之邑。其曰虚，又若无人耳。」</p><p>六四：王用亨于岐山，吉，无咎。象曰：「王用亨于岐山」，顺事也。</p><p>六四以柔顺之德居谦虚之位，顺之至也。昔者文王有君民之大德，又有事君之小心，故自处谦顺，而其德则升，其道则亨。故六四之升，有「王用亨于岐山」之象。盖谓文王尝用此至顺之道而亨于岐山矣。以是为亨，则吉于亨矣，其谁咎之乎？乃若后世之权臣强诸侯，不知王者有至顺之事，而包藏祸心，至于攘夺僭窃者，难免乎万世之咎矣，况欲吉，得乎？李博士曰：「孔子曰：我欲托之空言，不如载之行事为深切著明也。盖谓示后世已然之事，其功过于空言。」故明夷取于箕子，升取文王岐山，凡此亦载之行事，欲其深切著明也。</p><p>六五：贞吉，升阶。象曰：「贞吉升阶」，大得志也。彖</p><p>曰：「柔以时升。」盖谓五也。李博士曰：「凡人君皆升乎天位，而所以升则不同。有去民之害，顺乎天而升，若汤、武者矣；有功德被于天下，荐诸天而升，若舜、禹者矣。六五贞吉而后升阶，盖言于正既吉，升而有序，尧、舜、禹是也。故以阶言之，谓宾主以揖逊而升者也。」耿希道曰：「舜、禹之事，圣人所欲也。汤、武之事，岂圣人所欲哉？故贞吉升阶为大得志也。若夫明夷之九三，其所以大得者，乃南狩之志尔，非圣人之本心也。」</p><p>上六：冥升，利于不息之贞。象曰：「冥升」在上，消不富也。升至上六，无所复升矣。坤阴既极，冥昧无睹，故曰「冥升」。夫消息盈虚之理，曷可常也？有息必有消，有盈必有虚。升至上六，无所复升矣，而犹不已，则有消而无息，有虚而无盈矣。上六曾不知此，冥于升者也，故曰：「冥升在上，消不富也。」然以上六不知止息之心，用之或得其正，则又利矣。故复晓之曰：「利于不息之贞」。孟子曰：「仁义忠信，乐善不倦，此天爵也。」此「不息之贞」也。惟施于此为利，若施于消息盈虚之际，则不富矣。䷮</p><p>坎下兑上 困亨。贞，大人吉，无咎。有言不信。彖曰：困，刚揜也。险以说，困而不失其所亨，其唯君子乎？「贞，大人吉」，以刚中也。「有言不信」，尚口乃穷也。</p><p>易之六爻，大率以阳为君子，阴为小人。如姤、复等卦，则阴阳虽分多寡，而有消长之渐。至泰至否，则阴阳之势均矣，然亦大率以往来屈信为君子、小人之胜负。至困，则阴阳之势亦均。此虽非消长之卦，不以往来屈信论，而阳爻又杂于群阴之中，为之掩隔，此君子不偶之象也。故圣人名其卦曰「困」。而彖曰：「困，刚揜也。」所谓刚者，九二、九四、九五是也。二之刚为初与三之所揜，四与五之刚为三与上之所揜，故曰：「困，刚揜也。」此指三阳爻见揜于三阴，以言困也。「险以说」，此又合坎、兑二体之用，以言乎困之道也。夫困也者，所谓险难之时也。当险难之时，而能说以处之，则乐天安义，而不失其所守，故时虽困矣，而其道则亨也。夫时虽困而道则亨，此非君子不能也。故继之以困而不失其所亨，其惟君子乎！子思子曰：「君子素患难而行乎患难，无入而不自得焉。」此之谓也。若小人，则安平无事之时，犹失所守，况当险难之时乎？又焉得亨矣。正，大人吉，以刚中也。此又指二五之刚中，而能尽处困之道也。夫「正」者，在天则为命，在人则为性，而在事与物则为理。古今有殊时，而此正则不变。万物有成败，而此正则固存。故是正者，在困之爻，则二五是也，在人则大人是也。何者？以其刚中故也。其中也刚，则此正不移，投之困穷险难之地，何往而不吉乎？非能吉也，能不失其正，故「吉」也。或曰君子，或曰大人云者，亦无异义也。卦德于「大人吉」之后，又继之以无咎之辞，谓当此之时，以大人之德，不能无困，然在我者有处困之道，故有「吉」而「无咎」也。彖文省此二字者，谓既「吉」则「无咎」矣。朱子发引范谔昌之言曰：「彖文脱无咎二字，恐未必然。」有言不信，尚口乃穷也。此又指兑说在上，或至于尚口，以为处困之戒也。夫当险难之时，固在于说以处之，然不知自说之道，而徒尚口舌以求说于人，欲以免夫困，人谁信之哉？祗自取困穷尔，故曰「有言不信，尚口乃穷也」。前言以说处困而亨，此又言尚口乃穷者，盖言当此之时，自说可也，说人不可也。此圣人重复发明兑说之旨，恐万世之下，处困之君子，误用其心也。</p><p>象曰：泽无水，「困」，君子以致命遂志。</p><p>泽也者，水之所钟之地也。今也坎水在下，兑泽在上，见泽而不见水，泽无水者也。夫其泽存，其水亡，此困乏之义也，故为「困」之象。君子当困穷之时，而至于空乏其身，行拂乱其所为，宜然而不然，若泽之无水焉者，此世人所谓有不可知者存也。而君子于此，则务致其命焉。子曰：「不知命，无以为君子也。」又曰：「穷理尽性，以至于命。」君子之学不至于命，如处困穷何？故处困穷之道，在于致命，谓欲至其所至之地也。命之学至之而无余，则在我之志者，亦无所不遂者矣。君子之志，志于行吾义而已。学而不至于命，则一为穷困患难之所撄，必至于丧其所守矣，义何在焉？故夫知义与命之为一者，可与处困矣。</p><p>初六：臀困于株木，入于幽谷，三岁不觌。象曰：「入于幽谷」，幽不明也。夫柔之所附者，刚也。刚既见揜，则柔亦失所附矣。夫刚揜则刚困，柔失所附则柔困。故初之与四，虽居相应之地，然四方困于见揜而未能下应于初，初欲上应于四，又为九二之刚所碍，则居失所安矣，故有「臀困于株木」之象。「株木」，指九二也。夫阴柔之人一有所碍，遂不能安其所遇，而至于迷惑自失，入于困穷幽暗之地，放曰：入于幽谷，谓坎险之底。而不能自拔也。夫不能自拔于幽暗之地，则虽上有九四之应也，三岁之久，其能觌乎？此无他，阴柔之人既无明见，一遇困难，遂至颠冥失错，理固然也。故象曰：「入于幽谷，幽不明也。」</p><p>九二：困于酒食，朱绂方来，利用享祀。征凶，无咎。象曰：「困于酒食」，中有庆也。彖</p><p>曰：「正大人吉」，以刚中也。夫以大人刚中之才，而处人臣正中之位，则九二是也。九二以刚居中，则安其所遇，故虽困穷险难，曾何足以动其心？但处人臣正中之位，而未能推君之惠泽以充足天下之愿欲，而使之饱满酣适焉，则吾以是为困也。故曰：「困于酒食。」虽然，二五之大人以正相应，亦不终困也。故又曰：「朱绂方来，利用享祀。」盖「朱绂方来」云者，五之下接乎二也。「利用享祀」云者，二之上通乎五也。夫「朱绂」之为服者，王者所以蔽膝也。九五方来，下接乎二，故取蔽膝之服以为象。享祀之礼，以至诚默通乎神明者也。九二自守于下，利用至诚以上通乎五，故取享祀之礼以为喻。夫上有以接乎下，而下有以通乎上，此大人以正相与，而不终困者然也。然又以「征凶无咎」戒之者，谓方困之时，为九二者，若不知以至诚自守，而往求遇合，此非大人之道也。犯难罹凶，乃其自取尔，又谁咎乎？夫以九二之刚中，犹不免于戒，处困之道，庸可易乎？故象又申之曰：「困于酒食，中有庆也。」盖谓当是时也，虽未能推君之惠泽以遍及天下，惟以刚中自守，而无庸有所往焉，则自有「朱绂方来」之庆矣。程河南曰：「自昔贤哲困于幽远，而德卒升闻，道卒为用者，惟自守至诚而已。」</p><p>六三：困于石，据于蒺藜，入于其宫，不见其妻，凶。象曰：「据于蒺藜」，乘刚也。「入于其宫，不见其妻」，不祥也。</p><p>「石」，坚重之物也，而非阴柔之才所能胜也。往而犯之，祇自困尔。故系辞曰：「非所困而困焉，名必辱。」谓九四、九五二刚在上，坚重不可犯也，而三犯之以取困也。蒺藜，蔓草之有角刺者。不正之人滥乘非据，而处正人之上，岂所安也？故系辞曰：「非所据而据焉，身必危。」谓九二之刚中，岂可乘也？而三乘之，非其所安，犹藉刺负芒然也。夫六三所以轻犯二刚以取困者，徒以上六吾配故也。六三阴也而居阳，自以为阳也，故求配于上六。然上六宫则是也，而非其妻，故曰：「入于其宫，不见其妻。」小人轻进妄动，无与亲合，危辱困极如此，岂吉祥之征也哉？故不免于凶祸也。系辞于此，又言其所以凶也，而曰：「既危且辱，死期将至，妻其可得见邪？」盖甚之也。以是观之，当困之时，不善处困者，三阴之爻皆然也。然君子为之商其尤不善者，六三是也。初六次之，上六又次之。</p><p>九四：来徐徐，困于金车，吝，有终。象曰：「来徐徐」，志在下也。虽不当位，有与也。</p><p>「坎」中之一阳，下碍初六，故曰「株木」。其为材也刚上冲九四，故曰「金车」。凡此皆九二之象也。夫初既「困于株木」，而不能上进，四又「困于金车」，而不能下逮，何咎如之？然九二有「朱绂方来」之庆，九五又有「徐有说」之理，二、五自以同德相应，而九四应初之志，可以徐徐而来也。「徐徐」，谓有困窒而未遽前也。夫处不当之位，动辄有碍，而未遽如意，所赖者有与在下，终必遂志，非终困也，故虽「吝」而「有终」。河南曰：「有终者，事之所归者正也。初、四正应，终必相从也。寒士之妻，弱国之臣，各安其正。苟择势而从，则恶之大者，不容于世矣！」</p><p>九五：劓刖，困于赤绂。乃徐有说，利用祭祀。象曰：「劓刖」，志未得也；「乃徐有说」，以中直也。「利用祭祀」，受福也。彖</p><p>曰：「正大人吉」，以刚中也。夫以大人刚中之才，而处人君正中之位，则九五是也。然当困之时，刚有所揜而志未得通，故有「劓刖」之象。「劓」之谓伤于上也；「刖」之谓伤于下也。上下皆揜于阴，为其伤害故也。夫五之困如此，故远近隔绝，应效未至，故其说未遽有也，故徐徐焉尔。而象又推原九五所以致说之道，而曰「中直也」。盖言二五大人以此道相许久矣，但时方困，刚方揜，故其说徐有也。祭祀者，人君所以礼神也。夫祭祀之事，必以诚敬为主，而后𫉬福祐之报。九五之下交于二也，不以诚敬默通乎二，安能获其应助之力乎？故曰：「利用祭祀，受福也。」夫二、五皆以至诚相感通，故同以祀事明之。然要之，获应助之力者，五也，此「受福也」之言，所以独归之五焉。礼有祭天神、祀地祇、享人鬼之别。五居尊，故言祭；二在下，故言享，各以其所当用也。上六：困于葛藟，于臲卼。曰动悔有悔，征吉。象曰：「困于葛藟」，未当也；「动悔有悔」，吉行也。</p><p>「困」至上六，困之极矣。六三非其正应也，徒以阴柔相缠系而已，非果能脱己之困束也，故「困于葛藟」，九五不可乘也。阳刚中正之君，方务去刚揜之困，而上以阴柔乘之，岂其所安？故又曰：「于臲卼」。夫上六有此二困，而不知物极则反，困极则通，何也？无乃自谋之拙乎？曰云者，自谋之辞也。如是自谋，曰动则有悔也，姑求安于「臲卼」之地，而甘心于缠系之人也，而不知不动乃所以有悔也。然则为上六者，又何锢于不动，而以动为讳乎？故圣人于此明以告之以「征吉」，谓其舍「臲卼」，乃所以安释缠系，乃所以脱其困束也。由是观之，甘心于缠系者，未为计之当也。若以动为悔，乃所以有悔也，则莫若吉于行也。圣人所以为上六谋者，至此可谓审矣。为上六者，舍其自谋以从圣人可也。朱子发曰：「范睢困于郑安平，虞卿困于魏齐，犹能解相印以全其躯，况体易之君子乎？」童溪易传卷二十一，</p>',43)])])}const m=t(r,[["render",i]]);export{h as __pageData,m as default};
